  funcLuaMenuCommand(C.MESH_VISIBLE, L, M_SIXTH_TITLE, hiper or ptype == 3, 0)
  funcLuaMenuCommand(C.MESH_VISIBLE, L, M_SIXTH_BASE, ptype == 3, 0)
