  local name = HyperPageNameWithType(HyperPageName(skill), skill)
  if name ~= nil then
    funcLuaMenuCommand(C.TEXT, L_DETAIL, 1704438437 --[[_text_name01]], name, 0)
  end
  return true, "detail"
end

