  funcLuaMenuCommand(C.TEXT_VISIBLE, L, 1899787537 --[[_text_area01]], false, 0)
  funcLuaMenuCommand(C.MESH_VISIBLE, L, 3516146179 --[[_area_base01]], false, 0)
