CharacterReforged.HYPER_PAGE_TEAM02 = 3964676290 --[[#/menu/102_team/team02/team02_02/<LG>/team02_02.g4tx]]
CharacterReforged.hyper_page.peg_info = CharacterReforged.hyper_card.peg_info
