CharacterReforged.hyper_page.band = CharacterReforged.hyper_card.band

if CharacterReforged.HYPER_PAGE_MIXIMAX_VIEW == nil then
  CharacterReforged.HYPER_PAGE_MIXIMAX_VIEW = false
